export function translate(locale: Locale, key: TranslationKey): string {
  const value = dictionaries[locale]?.[key] ?? english[key];
  const start = key.startsWith(" ") ? " " : "";
  const end = key.endsWith(" ") ? " " : "";
  return start + value.trim() + end;
}

export function translateDynamic(locale: Locale, key: string): string {
  return Object.prototype.hasOwnProperty.call(english, key) ? translate(locale, key as TranslationKey) : key;
}
